sp_widget.client_script:
function($scope, $location) {
  $scope.goTo = function(url) {
    // Abre o link em uma nova aba
    window.location.href = url;
  };

	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

}

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

html, body {
  height: 100%;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Roboto Flex', sans-serif;
  background: #fff;
  text-align: center;
}

.center-widget {
   font-family: 'Roboto Flex', sans-serif;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, 30%); /* desce o bloco visualmente */
  max-width: 500px;
  width: 90%;
  text-align: center;
}

.center-widget .back-link {
  display: inline-block;
  margin-bottom: 2rem; /* afasta o link do título */
  font-size: 2rem;
  color: #293273;
  text-decoration: none;
  font-weight: 500;
  transition: color 0.3s;
  text-decoration: underline;
  transform: translateY(-30px);
  cursor: pointer;
}


.center-widget .back-link:hover {
  color: #0056b3;
 // text-decoration: underline;
}


.center-widget .title {
   font-family: 'Roboto Flex', sans-serif;
  font-weight: 300;
  font-size: 2.8rem;
   margin-top: -1rem;
  margin-bottom: 1rem;
  color: #333;
}

.center-widget img {
  max-width: 500px;
  max-height: 500px;
  width: 100%;
  height: auto;
  margin-bottom: 1rem;
}

.center-widget .error-text {
  font-weight: 600;
  font-size: 1rem;
  color: #293273;
   font-family: 'Roboto Flex', sans-serif;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Responsivo */
@media (max-width: 600px) {
  .center-widget .title {
    font-size: 1.5rem;
  }
  .center-widget .error-text {
    font-size: 1rem;
  }
}

@media (max-width: 540px) {
  .center-widget {
    transform: translate(-50%, 60%);
  }

  .center-widget .title {
    font-size: 1.4rem;
  }

  .center-widget .error-text {
    font-size: 1rem;
  }

  .center-widget img {
    max-width: 100%;
    height: auto;
  }
}
@media (max-width: 440px) {
  .center-widget {
    transform: translate(-50%, 80%);
  }

  .center-widget .title {
    font-size: 1.4rem;
  }

  .center-widget .error-text {
    font-size: 1rem;
  }

  .center-widget img {
    max-width: 100%;
    height: auto;
  }
}

@media (max-width: 350px) {
  .center-widget {
    transform: translate(-50%, 100%);
  }

  .center-widget .title {
    font-size: 1.4rem;
  }

  .center-widget .error-text {
    font-size: 1rem;
  }

  .center-widget img {
    max-width: 100%;
    height: auto;
  }
}
